	constexpr T A(1.00746054f); // 1 / 1! in Taylor series
	constexpr T B(0.45053901f); // 1 / 2! in Taylor series
	constexpr T C(0.25724632f); // 1 / 3! in Taylor series
	return 1 / (1 + A * X + B * X * X + C * X * X * X);		
}

